		gameWS.onmessage=function(k){
		
		    var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.hjh.dwt!=undefined){
			
			if(gameController.rqk!=parseInt(tmpMess[1])){
				
			gameController.rqk=parseInt(tmpMess[1]);	
			gameController.dyn=parseInt(tmpMess[1]);	
			gameController.hjh.dwt.rgq("creditd", "#gek", [gameController.tiu(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
